    r = a % 4
    return 1 if r == 1 else -1 if r == 3 else 0

def twisted_power_sum(k: int, m: int, x: int) -> int:
    if k < 0 or m < 0:
        raise ValueError("k and m must be nonnegative")
    return sum(chi_four(a) * (x + a) ** k for a in range(1, m + 1))

def is_even_power(value: int, n: int) -> bool:
    if n < 2 or n % 2: raise ValueError("n must be even and at least 2")
    if value < 0: return False
    return any(y**n == value for y in range(0, value + 1))

if __name__ == "__main__":
    for q in range(1, 6):
        value = twisted_power_sum(2, 4*q, 0)
        print(q, value, [is_even_power(value, n) for n in (2, 4, 6)])
    print("square outside range:", twisted_power_sum(2, 4, -3), "= 2^2")
    print("odd power:", twisted_power_sum(1, 16, 9), "= (-2)^3")

